"""Standard steel section database.

I-shapes: AISC (USA) and CISC (Canada) W, HP, M and S sections.
Hollow sections: AISC and CISC rectangular, square and round HSS, plus AISC pipe.
Dimensions are millimetres; areas mm2; moments of inertia mm4.

Sources: AISC Shapes Database v15.0 and CISC Structural Section Tables
SST12.1, retrieved from the public Optimal Beam steel section API on
2026-11-12. Verify critical values against the publisher before design.
"""

